import re
p='simlib.py'; s=open(p).read()
s=s.replace('cmd = {"type": "run"','cmd = {"kind": "run"')
s+='''
def cmd(chat_id, payload):
    return rpc("QueueCommand", {"chatId": chat_id, "command": payload})

def interrupt(chat_id):
    return cmd(chat_id, {"kind": "interrupt"})

def tool(chat_id, name, args=None, call_id=None):
    p = {"chatId": chat_id, "tool": name, "args": args or {}}
    if call_id: p["toolCallId"] = call_id
    return rpc("BotTool", p)["text"]

def work(work_id):
    return next((w for w in records().get("work", []) if w["id"] == work_id), None)

def status(chat_id):
    return next((x for x in sessions() if x["chatId"] == chat_id), None)

def wait(pred, timeout=30, every=0.5):
    t=time.time()
    while time.time()-t < timeout:
        v = pred()
        if v: return v
        time.sleep(every)
    return None
'''
open(p,'w').write(s)
EOF
